#define SCB_CSR_AIRCR_INIT          1

/*
//    <o>  Deep Sleep can be enabled by
//      <0=>  Secure and Non-Secure state
//      <1=>  Secure state only
//      <i>  Value for SCB->CSR register bit DEEPSLEEPS
*/
#define SCB_CSR_DEEPSLEEPS_VAL      1           /*!< Value for SCB->CSR register bit DEEPSLEEPS                                */

/*
//    <o>  System reset request accessible from
//      <0=>  Secure and Non-Secure state
//      <1=>  Secure state only
//      <i>  Value for SCB->AIRCR register bit SYSRESETREQS
*/
#define SCB_AIRCR_SYSRESETREQS_VAL  1           /*!< Value for SCB->AIRCR register bit SYSRESETREQS                            */

/*
//    <o>  Priority of Non-Secure exceptions is
//      <0=>  Not altered
//      <1=>  Lowered to 0x80-0xFF
//      <i>  Value for SCB->AIRCR register bit PRIS
*/
#define SCB_AIRCR_PRIS_VAL          1           /*!< Value for SCB->AIRCR register bit PRIS                                    */

/*
//    <o>  BusFault, HardFault, and NMI target
//      <0=>  Secure state
//      <1=>  Non-Secure state
//      <i>  Value for SCB->AIRCR register bit BFHFNMINS
*/
#define SCB_AIRCR_BFHFNMINS_VAL     0           /*!< Value for SCB->AIRCR register bit BFHFNMINS                               */

